  line-height: 1.35; margin-bottom: 10px; font-weight: 400;
}
.card-text { font-size: 0.88rem; color: var(--gray-500); line-height: 1.6; margin-bottom: 16px; }
.card-date { font-size: 0.78rem; color: var(--gray-400); }
.card-link { color: var(--primary); font-weight: 600; font-size: 0.88rem; }
.card-link:hover { color: var(--primary-light); }

/* ===== INSIGHT CARDS GRID ===== */
.insights-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; }
@media (max-width: 900px) { .insights-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 600px) { .insights-grid { grid-template-columns: 1fr; } }

/* Card image placeholder with skyline SVG */
.card-img-placeholder {
  width: 100%; height: 200px; display: flex; align-items: center; justify-content: center;
  background: linear-gradient(135deg, var(--primary-dark) 0%, var(--primary) 100%);
  position: relative; overflow: hidden;
}
.card-img-placeholder svg { width: 80px; height: 80px; opacity: 0.2; }
.card-img-placeholder::after {
  content: ''; position: absolute; bottom: 0; left: 0; right: 0; height: 60%;
  background: linear-gradient(to top, rgba(0,63,45,0.4), transparent);
}

/* ===== FEATURED INSIGHTS (3-col) ===== */
.featured-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; }
@media (max-width: 900px) { .featured-grid { grid-template-columns: 1fr; } }

.featured-card {
  display: flex; flex-direction: column; border-radius: 6px; overflow: hidden;
  border: 1px solid var(--gray-200); transition: transform var(--transition), box-shadow var(--transition);
  background: var(--white);
}
.featured-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }

/* ===== ANNOUNCEMENT BANNER ===== */
.announcement {
  background: var(--navy); padding: 20px 0; text-align: center;
  border-bottom: 2px solid var(--accent-gold);
}
.announcement-inner {
  display: flex; align-items: center; justify-content: center; gap: 24px; flex-wrap: wrap;
}
.announcement p { color: rgba(255,255,255,0.9); font-size: 0.95rem; font-weight: 500; }
.announcement .btn { padding: 8px 20px; font-size: 0.82rem; }

/* ===== ABOUT STATEMENT ===== */
.about-statement {
  display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center;
}
.about-statement-text h2 {
  font-family: var(--font-display); font-size: clamp(1.6rem, 2.5vw, 2.2rem);
  color: var(--gray-900); line-height: 1.25; margin-bottom: 20px;
}
.about-statement-text p { color: var(--gray-600); line-height: 1.8; margin-bottom: 24px; }
.about-statement-visual {
  position: relative; height: 380px; border-radius: 8px; overflow: hidden;
  background: linear-gradient(135deg, var(--primary-dark), var(--primary));
}
.about-visual-pattern {
  position: absolute; inset: 0; opacity: 0.08;
  background-image:
    repeating-linear-gradient(45deg, transparent, transparent 35px, rgba(255,255,255,0.1) 35px, rgba(255,255,255,0.1) 36px),
    repeating-linear-gradient(-45deg, transparent, transparent 35px, rgba(255,255,255,0.1) 35px, rgba(255,255,255,0.1) 36px);
}
.about-visual-content {
  position: absolute; bottom: 32px; left: 32px; right: 32px; color: var(--white);
}
.about-visual-content h3 { font-family: var(--font-display); font-size: 1.4rem; margin-bottom: 4px; }
.about-visual-content p { font-size: 0.85rem; opacity: 0.7; }

@media (max-width: 900px) {
  .about-statement { grid-template-columns: 1fr; gap: 32px; }
  .about-statement-visual { height: 260px; }
}

/* ===== WHAT WE DO TABS ===== */
.wwd-container { display: grid; grid-template-columns: 280px 1fr; gap: 0; min-height: 340px; }
.wwd-tabs {
  display: flex; flex-direction: column; border-right: 2px solid var(--gray-200);
}
.wwd-tab {
  padding: 22px 28px; text-align: left; font-size: 0.95rem; font-weight: 500;
  color: var(--gray-500); border: none; background: none; cursor: pointer;
  border-left: 3px solid transparent; transition: all var(--transition);
  font-family: var(--font-body); position: relative;
}
.wwd-tab:hover { color: var(--gray-700); background: var(--gray-50); }
.wwd-tab.active {
  color: var(--primary); border-left-color: var(--primary); background: var(--gray-50);
  font-weight: 600;
}
.wwd-panel {
  display: none; padding: 32px 48px; animation: fadeInPanel 0.35s ease;
}
.wwd-panel.active { display: block; }
@keyframes fadeInPanel { from { opacity: 0; transform: translateX(10px); } to { opacity: 1; transform: translateX(0); } }
.wwd-panel h3 {
  font-family: var(--font-display); font-size: 1.5rem; color: var(--gray-900);
  margin-bottom: 16px;
}
.wwd-panel p { color: var(--gray-600); line-height: 1.8; margin-bottom: 8px; }
.wwd-panel ul { margin: 16px 0; display: flex; flex-direction: column; gap: 8px; }
.wwd-panel li {
  padding-left: 20px; position: relative; font-size: 0.92rem; color: var(--gray-600);
}
.wwd-panel li::before {
  content: ''; position: absolute; left: 0; top: 8px;
  width: 8px; height: 8px; border-radius: 50%; background: var(--accent-teal);
}

@media (max-width: 768px) {
  .wwd-container { grid-template-columns: 1fr; }
  .wwd-tabs { flex-direction: row; border-right: none; border-bottom: 2px solid var(--gray-200); overflow-x: auto; }
  .wwd-tab { border-left: none; border-bottom: 3px solid transparent; white-space: nowrap; padding: 16px 20px; font-size: 0.85rem; }
  .wwd-tab.active { border-bottom-color: var(--primary); border-left-color: transparent; }
  .wwd-panel { padding: 24px 0; }
}

/* ===== NEWSLETTER ===== */
.newsletter {
  background: linear-gradient(135deg, var(--primary-dark) 0%, var(--primary) 100%);
  padding: 64px 0; position: relative; overflow: hidden;
}
.newsletter::before {
  content: ''; position: absolute; inset: 0;
  background: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.04'/%3E%3C/svg%3E");
  pointer-events: none;
}
.newsletter-inner {
  position: relative; z-index: 2;
  display: flex; align-items: center; justify-content: space-between; gap: 40px; flex-wrap: wrap;
}
.newsletter-text h2 { font-family: var(--font-display); font-size: 1.8rem; color: var(--white); margin-bottom: 8px; }
.newsletter-text p { color: rgba(255,255,255,0.7); font-size: 0.95rem; }
.newsletter-form { display: flex; gap: 12px; }
.newsletter-form input {
  padding: 14px 20px; background: rgba(255,255,255,0.1); border: 1px solid rgba(255,255,255,0.25);
  border-radius: var(--radius); color: var(--white); font-size: 0.9rem; min-width: 280px;
  font-family: var(--font-body);
}
.newsletter-form input::placeholder { color: rgba(255,255,255,0.5); }
.newsletter-form input:focus { outline: none; border-color: var(--accent-gold); background: rgba(255,255,255,0.15); }

@media (max-width: 768px) {
  .newsletter-inner { flex-direction: column; text-align: center; }
  .newsletter-form { flex-direction: column; width: 100%; }
  .newsletter-form input { min-width: auto; width: 100%; }
}

/* ===== COMMITMENT PILLARS ===== */
.commitment-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
.commitment-card {
  padding: 32px 24px; border-radius: 6px; background: var(--white);
  border: 1px solid var(--gray-200); transition: all var(--transition);
  text-align: center;
}
.commitment-card:hover { border-color: var(--primary); box-shadow: var(--shadow-md); transform: translateY(-2px); }
.commitment-icon {
  width: 56px; height: 56px; margin: 0 auto 18px; border-radius: 50%;
  background: linear-gradient(135deg, var(--primary), var(--accent-teal));
  display: flex; align-items: center; justify-content: center;
}
.commitment-icon svg { width: 24px; height: 24px; color: var(--white); }
.commitment-card h3 { font-family: var(--font-display); font-size: 1.1rem; color: var(--gray-900); margin-bottom: 10px; }
.commitment-card p { font-size: 0.85rem; color: var(--gray-500); line-height: 1.6; margin-bottom: 16px; }

@media (max-width: 900px) { .commitment-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 600px) { .commitment-grid { grid-template-columns: 1fr; } }

/* ===== SERVICE CATEGORIES GRID ===== */
.services-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; }
.service-card {
  padding: 36px 28px; background: var(--white); border-radius: 6px;
  border: 1px solid var(--gray-200); transition: all var(--transition);
  position: relative; overflow: hidden;
}
.service-card::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px;
  background: linear-gradient(90deg, var(--primary), var(--accent-teal));
  transform: scaleX(0); transform-origin: left; transition: transform var(--transition);
}
.service-card:hover::before { transform: scaleX(1); }
.service-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-3px); }
.service-card-icon {
  width: 48px; height: 48px; border-radius: 8px; margin-bottom: 20px;
  background: var(--gray-50); display: flex; align-items: center; justify-content: center;
}
.service-card-icon svg { width: 24px; height: 24px; color: var(--primary); }
.service-card h3 { font-family: var(--font-display); font-size: 1.2rem; color: var(--gray-900); margin-bottom: 12px; }
.service-card p { font-size: 0.88rem; color: var(--gray-500); line-height: 1.65; margin-bottom: 20px; }

@media (max-width: 900px) { .services-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 600px) { .services-grid { grid-template-columns: 1fr; } }

/* ===== CAPABILITIES GRID ===== */
.capabilities-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.capability-card {
  padding: 32px 24px; background: var(--white); border-radius: 6px;
  border: 1px solid var(--gray-200); transition: all var(--transition);
}
.capability-card:hover { border-color: var(--primary); box-shadow: var(--shadow-md); }
.capability-card h3 {
  font-family: var(--font-display); font-size: 1.05rem; color: var(--gray-900);
  margin-bottom: 10px; display: flex; align-items: center; gap: 10px;
}
.capability-card h3 .cap-dot {
  width: 8px; height: 8px; border-radius: 50%; background: var(--accent-teal); flex-shrink: 0;
}
.capability-card p { font-size: 0.85rem; color: var(--gray-500); line-height: 1.65; }

@media (max-width: 900px) { .capabilities-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 600px) { .capabilities-grid { grid-template-columns: 1fr; } }

/* ===== FEATURED TOPICS ===== */
.topics-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
.topic-card {
  padding: 28px 20px; background: var(--gray-50); border-radius: 6px;
  text-align: center; transition: all var(--transition); border: 1px solid transparent;
}
.topic-card:hover { background: var(--white); border-color: var(--primary); transform: translateY(-2px); }
.topic-card h3 { font-family: var(--font-display); font-size: 1rem; color: var(--gray-900); }

@media (max-width: 768px) { .topics-grid { grid-template-columns: repeat(2, 1fr); } }

/* ===== TESTIMONIAL ===== */
.testimonial-block {
  background: var(--gray-50); border-radius: 8px; padding: 48px; position: relative;
  border-left: 4px solid var(--accent-gold);
}
.testimonial-block .quote-mark {
  font-family: var(--font-display); font-size: 4rem; color: var(--accent-gold);
  line-height: 1; margin-bottom: -16px; opacity: 0.4;
}
.testimonial-block blockquote {
  font-family: var(--font-display); font-size: 1.2rem; color: var(--gray-800);
  line-height: 1.6; font-style: italic; margin-bottom: 20px;
}
.testimonial-block cite {
  font-size: 0.88rem; color: var(--gray-500); font-style: normal; font-weight: 600;
}

/* ===== PARTNERSHIP HIGHLIGHT ===== */
.partnership {
  display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center;
}
.partnership-visual {
  height: 320px; border-radius: 8px; overflow: hidden; position: relative;
  background: linear-gradient(135deg, var(--primary-dark), var(--accent-teal));
}
.partnership-visual-inner {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
}
.partnership-visual svg { width: 120px; height: 120px; opacity: 0.15; }
.partnership-stats { display: flex; gap: 32px; margin-top: 28px; }
.partnership-stat { text-align: center; }
.partnership-stat .stat-num {
  font-family: var(--font-display); font-size: 2rem; color: var(--primary);
}
.partnership-stat .stat-label { font-size: 0.78rem; color: var(--gray-500); margin-top: 4px; }

@media (max-width: 900px) {
  .partnership { grid-template-columns: 1fr; gap: 32px; }
  .partnership-visual { height: 240px; }
}

/* ===== PROPERTY TYPES CTA ===== */
.property-types-row { display: flex; gap: 16px; flex-wrap: wrap; }
.property-type-badge {
  padding: 10px 20px; border-radius: 30px; font-size: 0.85rem; font-weight: 500;
  color: var(--gray-700); background: var(--white); border: 1px solid var(--gray-200);
  transition: all var(--transition); cursor: pointer;
}
.property-type-badge:hover { border-color: var(--primary); color: var(--primary); background: var(--gray-50); }

/* ===== RELATED SERVICES ===== */
.related-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
.related-card {
  display: flex; align-items: center; gap: 16px; padding: 20px 24px;
  background: var(--gray-50); border-radius: 6px; transition: all var(--transition);
  border: 1px solid transparent;
}
.related-card:hover { background: var(--white); border-color: var(--gray-200); box-shadow: var(--shadow-sm); }
.related-card h4 { font-size: 0.95rem; color: var(--gray-800); font-weight: 600; }
.related-card p { font-size: 0.8rem; color: var(--gray-500); margin-top: 2px; }
.related-card svg { width: 20px; height: 20px; color: var(--primary); flex-shrink: 0; }

@media (max-width: 600px) { .related-grid { grid-template-columns: 1fr; } }

/* ===== CAROUSEL ===== */
.carousel { position: relative; overflow: hidden; }
.carousel-track { display: flex; transition: transform 0.5s ease; }
.carousel-slide { min-width: 100%; padding: 0 4px; }
.carousel-controls {
  display: flex; gap: 12px; margin-top: 24px; justify-content: center;
}
.carousel-btn {
  width: 44px; height: 44px; border-radius: 50%; border: 1px solid var(--gray-300);
  background: var(--white); display: flex; align-items: center; justify-content: center;
  cursor: pointer; transition: all var(--transition);
}
.carousel-btn:hover { border-color: var(--primary); color: var(--primary); }
.carousel-btn svg { width: 18px; height: 18px; }
.carousel-dots { display: flex; gap: 8px; align-items: center; justify-content: center; margin-top: 16px; }
.carousel-dot {
  width: 8px; height: 8px; border-radius: 50%; background: var(--gray-300);
  transition: all var(--transition); cursor: pointer;
}
.carousel-dot.active { background: var(--primary); width: 24px; border-radius: 4px; }

/* ===== FOOTER ===== */
.site-footer { background: var(--navy); color: rgba(255,255,255,0.7); padding: 64px 0 0; }
.footer-grid {
  display: grid; grid-template-columns: 2fr repeat(3, 1fr); gap: 48px;
  padding-bottom: 48px; border-bottom: 1px solid rgba(255,255,255,0.1);
}
.footer-brand .logo { font-size: 1.4rem; margin-bottom: 16px; color: var(--white); }
.footer-brand p { font-size: 0.85rem; line-height: 1.7; max-width: 300px; color: rgba(255,255,255,0.5); }
.footer-col h4 {
  font-size: 0.72rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.12em; color: rgba(255,255,255,0.4); margin-bottom: 20px;
}
.footer-col a {
  display: block; padding: 4px 0; font-size: 0.88rem; color: rgba(255,255,255,0.6);
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }
.footer-bottom {
  display: flex; align-items: center; justify-content: space-between;
  padding: 24px 0; flex-wrap: wrap; gap: 16px;
}
.footer-bottom p { font-size: 0.78rem; color: rgba(255,255,255,0.35); }
.footer-legal { display: flex; gap: 20px; }
.footer-legal a { font-size: 0.78rem; color: rgba(255,255,255,0.35); }
.footer-legal a:hover { color: rgba(255,255,255,0.6); }

@media (max-width: 900px) {
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 600px) {
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .footer-legal { flex-wrap: wrap; justify-content: center; }
}

/* ===== ANIMATIONS ===== */
.fade-up {
  opacity: 0; transform: translateY(24px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}
.fade-up.visible { opacity: 1; transform: translateY(0); }
.fade-up-delay-1 { transition-delay: 0.1s; }
.fade-up-delay-2 { transition-delay: 0.2s; }
.fade-up-delay-3 { transition-delay: 0.3s; }
.fade-up-delay-4 { transition-delay: 0.4s; }

/* ===== BREADCRUMB ===== */
.breadcrumb {
  display: flex; align-items: center; gap: 8px; font-size: 0.8rem; margin-bottom: 16px;
}
.breadcrumb a { color: rgba(255,255,255,0.6); }
.breadcrumb a:hover { color: var(--white); }
.breadcrumb span { color: rgba(255,255,255,0.4); }
.breadcrumb .current { color: rgba(255,255,255,0.9); }

/* ===== DEAL FLOW CTA ===== */
.deal-cta {
  background: linear-gradient(135deg, var(--primary-dark), var(--primary));
  border-radius: 8px; padding: 48px; text-align: center; color: var(--white);
  position: relative; overflow: hidden;
}
.deal-cta::before {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(ellipse at 50% 0%, rgba(196,163,90,0.15), transparent 70%);
}
.deal-cta h3 { font-family: var(--font-display); font-size: 1.6rem; margin-bottom: 12px; position: relative; }
.deal-cta p { color: rgba(255,255,255,0.7); margin-bottom: 24px; position: relative; max-width: 500px; margin-left: auto; margin-right: auto; }

/* ===== INTRO STATEMENT ===== */
.intro-statement {
  max-width: 800px; padding: 0; font-size: 1.1rem; line-height: 1.8; color: var(--gray-600);
}

/* ===== PAGE LOAD ANIMATION ===== */
@keyframes heroSlideIn { from { opacity: 0; transform: translateY(30px); } to { opacity: 1; transform: translateY(0); } }
.hero-content { animation: heroSlideIn 0.8s ease-out 0.2s both; }
